-- DROP FUNCTION public.trg_set_gmt_modified();

CREATE OR REPLACE FUNCTION public.trg_set_gmt_modified()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.gmt_modified = CURRENT_TIMESTAMP;
RETURN NEW;
END;
$function$
;

