COMMENT ON COLUMN public.agent_schema.workspace_id IS 'workspace id';
COMMENT ON COLUMN public.agent_schema."name" IS 'agent name';
COMMENT ON COLUMN public.agent_schema.description IS 'agent description';
COMMENT ON COLUMN public.agent_schema."type" IS 'agent type: ReactAgent, ParallelAgent, SequentialAgent, LLMRoutingAgent, LoopAgent';
COMMENT ON COLUMN public.agent_schema.instruction IS 'system instruction';
COMMENT ON COLUMN public.agent_schema.input_keys IS 'input keys JSON';
COMMENT ON COLUMN public.agent_schema.output_key IS 'output key';
COMMENT ON COLUMN public.agent_schema.handle IS 'handle configuration JSON';
COMMENT ON COLUMN public.agent_schema.sub_agents IS 'sub agents configuration JSON';
COMMENT ON COLUMN public.agent_schema.yaml_schema IS 'generated YAML schema';
COMMENT ON COLUMN public.agent_schema.status IS 'agent status: DRAFT, PUBLISHED, ARCHIVED';
COMMENT ON COLUMN public.agent_schema.enabled IS 'enabled: 0-disabled, 1-enabled';
COMMENT ON COLUMN public.agent_schema.creator IS 'creator uid';
COMMENT ON COLUMN public.agent_schema.modifier IS 'modifier uid';

-- Table Triggers

create trigger trg_agent_schema_gmt_modified before
    update
    on
        public.agent_schema for each row execute function trg_set_gmt_modified();


