-- DROP TABLE workflow_span;

CREATE TABLE workflow_span ( id int8 GENERATED BY DEFAULT AS IDENTITY( INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 CACHE 1 NO CYCLE) NOT NULL, span_id varchar(64) NOT NULL, trace_id varchar(64) NOT NULL, parent_span_id varchar(64) NULL, span_name varchar(255) NULL, span_kind varchar(32) NOT NULL, sequence_no int4 NULL, node_id varchar(128) NULL, node_name varchar(255) NULL, node_type varchar(64) NULL, attempt_no int4 DEFAULT 0 NOT NULL, provider varchar(64) NULL, model_id varchar(128) NULL, model_name varchar(128) NULL, price_cost numeric(20, 8) DEFAULT 0 NOT NULL, status varchar(32) NOT NULL, start_time timestamptz(3) NOT NULL, end_time timestamptz(3) NULL, duration_ms int8 NULL, prompt_tokens int8 DEFAULT 0 NOT NULL, completion_tokens int8 DEFAULT 0 NOT NULL, total_tokens int8 DEFAULT 0 NOT NULL, input_data jsonb NULL, output_data jsonb NULL, span_data jsonb NULL, error_code varchar(64) NULL, error_message text NULL, error_data jsonb NULL, gmt_create timestamptz(3) DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT uk_workflow_span_span_id UNIQUE (span_id), CONSTRAINT workflow_span_pkey PRIMARY KEY (id));
CREATE INDEX idx_workflow_span_node_attempt ON public.workflow_span USING btree (trace_id, node_id, attempt_no, span_kind);
CREATE INDEX idx_workflow_span_status_start ON public.workflow_span USING btree (status, start_time DESC);
CREATE INDEX idx_workflow_span_trace_kind ON public.workflow_span USING btree (trace_id, span_kind);
CREATE INDEX idx_workflow_span_trace_node ON public.workflow_span USING btree (trace_id, node_id);
CREATE INDEX idx_workflow_span_trace_parent ON public.workflow_span USING btree (trace_id, parent_span_id);
CREATE INDEX idx_workflow_span_trace_start ON public.workflow_span USING btree (trace_id, start_time);
COMMENT ON TABLE public.workflow_span IS 'Workflow Trace Span，一次节点、模型或子工作流实际执行一条';

-- Column comments

COMMENT ON COLUMN public.workflow_span.span_id IS 'Span ID';
COMMENT ON COLUMN public.workflow_span.trace_id IS '所属 Trace ID';
COMMENT ON COLUMN public.workflow_span.parent_span_id IS '父 Span ID，用于构建链路树';
COMMENT ON COLUMN public.workflow_span.span_name IS 'Span 操作名称';
COMMENT ON COLUMN public.workflow_span.span_kind IS 'NODE/MODEL_CALL/SUB_WORKFLOW';
COMMENT ON COLUMN public.workflow_span.sequence_no IS '同一 Trace 内执行顺序';
COMMENT ON COLUMN public.workflow_span.node_id IS 'Workflow 节点 ID';
COMMENT ON COLUMN public.workflow_span.attempt_no IS '执行次数，第一次为 0';
COMMENT ON COLUMN public.workflow_span.price_cost IS '模型调用成本，单位元';
COMMENT ON COLUMN public.workflow_span.span_data IS 'SpanReporter 上报的扩展 KV';


-- public.workflow_trace definition

-- Drop table

-- DROP TABLE workflow_trace;

CREATE TABLE workflow_trace ( id int8 GENERATED BY DEFAULT AS IDENTITY( INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 CACHE 1 NO CYCLE) NOT NULL, trace_id varchar(64) NOT NULL, root_span_id varchar(64) NULL, task_id varchar(64) NOT NULL, request_id varchar(64) NULL, app_id varchar(64) NOT NULL, workflow_version varchar(64) NULL, conversation_id varchar(64) NULL, invoke_source varchar(32) NULL, status varchar(32) NOT NULL, finish_reason varchar(32) NULL, start_time timestamptz(3) NOT NULL, end_time timestamptz(3) NULL, duration_ms int8 NULL, prompt_tokens int8 DEFAULT 0 NOT NULL, completion_tokens int8 DEFAULT 0 NOT NULL, total_tokens int8 DEFAULT 0 NOT NULL, total_cost numeric(20, 8) DEFAULT 0 NOT NULL, span_count int4 DEFAULT 0 NOT NULL, model_call_count int4 DEFAULT 0 NOT NULL, input_data jsonb NULL, output_data jsonb NULL, trace_data jsonb NULL, error_data jsonb NULL, error_code varchar(64) NULL, error_message text NULL, gmt_create timestamptz(3) DEFAULT CURRENT_TIMESTAMP NOT NULL, gmt_modified timestamptz(3) DEFAULT CURRENT_TIMESTAMP NOT NULL, user_id varchar(32) NULL, CONSTRAINT uk_workflow_trace_task_id UNIQUE (task_id), CONSTRAINT uk_workflow_trace_trace_id UNIQUE (trace_id), CONSTRAINT workflow_trace_pkey PRIMARY KEY (id));
CREATE INDEX idx_workflow_trace_app_start_time ON public.workflow_trace USING btree (app_id, start_time DESC);
CREATE INDEX idx_workflow_trace_conversation ON public.workflow_trace USING btree (conversation_id, start_time DESC);
CREATE INDEX idx_workflow_trace_request_id ON public.workflow_trace USING btree (request_id);
CREATE INDEX idx_workflow_trace_status_start_time ON public.workflow_trace USING btree (status, start_time DESC);
COMMENT ON TABLE public.workflow_trace IS '工作流 Trace，一条记录代表一次完整工作流调用';

-- Column comments

COMMENT ON COLUMN public.workflow_trace.trace_id IS '业务 Trace ID';
COMMENT ON COLUMN public.workflow_trace.root_span_id IS '根 Span ID';
COMMENT ON COLUMN public.workflow_trace.task_id IS '工作流任务 ID';
COMMENT ON COLUMN public.workflow_trace.request_id IS '请求 ID';
COMMENT ON COLUMN public.workflow_trace.app_id IS '应用 ID';
COMMENT ON COLUMN public.workflow_trace.workflow_version IS '工作流/应用发布版本';
COMMENT ON COLUMN public.workflow_trace.conversation_id IS '会话 ID';
COMMENT ON COLUMN public.workflow_trace.invoke_source IS '调用来源：API/CONSOLE/ASYNC';
COMMENT ON COLUMN public.workflow_trace.status IS 'EXECUTING/SUCCESS/FAIL/STOP/PAUSE';
COMMENT ON COLUMN public.workflow_trace.finish_reason IS '结束原因：END/AUTO_END/FAIL/TIMEOUT/STOP/PAUSE';
COMMENT ON COLUMN public.workflow_trace.total_cost IS '模型调用总成本，单位元';
COMMENT ON COLUMN public.workflow_trace.input_data IS '本次工作流输入快照';
COMMENT ON COLUMN public.workflow_trace.output_data IS '本次工作流最终输出';
COMMENT ON COLUMN public.workflow_trace.trace_data IS 'Trace 扩展 KV 信息';
COMMENT ON COLUMN public.workflow_trace.error_data IS '结构化错误信息';


