INSERT INTO model (id, workspace_id, icon, "name", "type", "mode", model_id, provider, "enable", tags, "source", gmt_create, gmt_modified, creator, modifier, parameter_rules) VALUES(10052, '1', NULL, 'qwen-plus-latest', 'llm', 'chat', 'qwen-plus-latest', '4e0e12f3', true, 'web_search,reasoning,function_call', 'custom', '2026-10-15 11:22:37.025', '2026-10-19 09:53:49.847', NULL, NULL, '[{"max": 1, "min": 0, "code": "temperature", "help": {"en_US": "Controls randomness. Lower temperature results in less random completions. As the temperature approaches zero, the model will become deterministic and repetitive. Higher temperature results in more random completions.", "zh_Hans": "温度控制随机性。较低的温度会导致较少的随机完成。随着温度接近零，模型将变得确定性和重复性。较高的温度会导致更多的随机完成。"}, "name": "temperature", "type": "Number", "options": null, "required": false, "precision": 2, "description": "Controls randomness. Lower temperature results in less random completions. As the temperature approaches zero, the model will become deterministic and repetitive. Higher temperature results in more random completions.", "default_value": 0}, {"max": 1, "min": 0, "code": "top_p", "help": {"en_US": "Controls diversity via nucleus sampling: 0.5 means half of all likelihood-weighted options are considered.", "zh_Hans": "通过核心采样控制多样性：0.5表示考虑了一半的所有可能性加权选项。"}, "name": "top_p", "type": "Number", "options": null, "required": false, "precision": 2, "description": "Controls diversity via nucleus sampling: 0.5 means half of all likelihood-weighted options are considered.", "default_value": 1}, {"max": 1, "min": 0, "code": "presence_penalty", "help": {"en_US": "Applies a penalty to the log-probability of tokens already in the text.", "zh_Hans": "对文本中已有的标记的对数概率施加惩罚。"}, "name": "presence_penalty", "type": "Number", "options": null, "required": false, "precision": 2, "description": "Applies a penalty to the log-probability of tokens already in the text.", "default_value": 0}, {"max": 1, "min": 0, "code": "frequency_penalty", "help": {"en_US": "Applies a penalty to the log-probability of tokens that appear in the text.", "zh_Hans": "对文本中出现的标记的对数概率施加惩罚。"}, "name": "frequency_penalty", "type": "Number", "options": null, "required": false, "precision": 2, "description": "Applies a penalty to the log-probability of tokens that appear in the text.", "default_value": 0}, {"max": 4096, "min": 1, "code": "max_tokens", "help": {"en_US": "Specifies the upper limit on the length of generated results. If the generated results are truncated, you can increase this parameter.", "zh_Hans": "指定生成结果长度的上限。如果生成结果截断，可以调大该参数。"}, "name": "max_tokens", "type": "Number", "options": null, "required": false, "precision": 0, "description": "Specifies the upper limit on the length of generated results. If the generated results are truncated, you can increase this parameter.", "default_value": 512}, {"max": null, "min": null, "code": "seed", "help": {"en_US": "If specified, model will make a best effort to sample deterministically, such that repeated requests with the same seed and parameters should return the same result. Determinism is not guaranteed, and you should refer to the system_fingerprint response parameter to monitor changes in the backend.", "zh_Hans": "如��指定，模型将尽最大努力进行确定性采样，使得重复的具有相同种子和参数的请求应该返回相同的结果。不能保证确定性，您应该参考 system_fingerprint 响应参数来监视变化。"}, "name": "seed", "type": "Number", "options": null, "required": false, "precision": null, "description": "If specified, model will make a best effort to sample deterministically, such that repeated requests with the same seed and parameters should return the same result. Determinism is not guaranteed, and you should refer to the system_fingerprint response parameter to monitor changes.", "default_value": null}]'::jsonb);
