INSERT INTO application_version (id, app_id, workspace_id, config, status, "version", description, gmt_create, gmt_modified, creator, modifier) VALUES(10105, '2110572111089950721', '1', '{"nodes":[{"id":"1773714841659","type":"Start","name":"用户输入","desc":"","position":{"x":0,"y":704},"width":242,"config":{"input_params":[],"output_params":[{"key":"user_stage","type":"String","desc":"用户阶段","required":false,"default_value":""}],"node_param":{"imported_dify":{"selected":true,"title":"用户输入","type":"start","variables":[{"default":"","hint":"","label":"用户阶段","max_length":256,"options":[],"placeholder":"","required":false,"type":"text-input","variable":"user_stage"}]}}}},{"id":"llm","type":"LLM","name":"LLM A 分析原因","desc":"","position":{"x":2112,"y":8},"width":242,"config":{"input_params":[],"output_params":[{"key":"output","type":"String","desc":"文本输出"},{"key":"reasoning_content","type":"String","desc":"深度思考内容"}],"node_param":{"sys_prompt_content":"你是一个亲子沟通问题澄清助手。\n\n家长刚刚描述了一个亲子困扰，见${1779180563855.output}。你的任务不是立刻给方案，而是帮助家长先判断：这个问题背后更可能是哪几种情况。请你根据家长的求助内容、孩子档案摘要，从以下有9类亲子困境机制，并用家长能理解的话解释。\n\n9类机制如下：\n${conversation.NineType}\n\n\n非常重要：\n1. 不要使用“【XXX型】”这种生硬标签。\n2. 必须一次性输出9个方向，输出时，请按照该问题背后机制的可能性大小，从大到小进行排序。\n3. 每个方向都要结合用户问题，但不能机械套模板。\n4. 每项控制在1–2句话。\n5. 不要在这个节点给具体解决方案。\n\n请严格按以下格式输出：\n{\n  \"options\": [\n    { \"id\": \"label_attribution\", \"title\": \"你现在可能认为是孩子的品质问题\", \"desc\": \"描述对应的内容\" },\n    { \"id\": \"instant_reward\", \"title\": \"孩子可能被这件事带来的即时满足吸引\", \"desc\": \"描述对应的内容\" },\n    { \"id\": \"avoidance\", \"title\": \"孩子可能是在借这个行为躲开别的压力\", \"desc\": \"描述对应的内容\" },\n    { \"id\": \"interaction_cycle\", \"title\": \"你们可能已经进入了越管越对抗的循环\", \"desc\": \"描述对应的内容\" },\n    { \"id\": \"expectation_gap\", \"title\": \"您的期待和孩子当前状态之间可能有落差\", \"desc\": \"描述对应的内容\" },\n    { \"id\": \"parent_anxiety\", \"title\": \"您的担心可能已经被放大了\", \"desc\": \"描述对应的内容\" },\n    { \"id\": \"boundary_unclear\", \"title\": \"家里可能还没有把规则和边界说清楚\", \"desc\": \"描述对应的内容\" },\n    { \"id\": \"skill_deficit\", \"title\": \"孩子可能还缺少处理这件事的具体能力\", \"desc\": \"描述对应的内容\" },\n    { \"id\": \"psychological_risk\", \"title\": \"这件事背后可能还有心理状态风险\", \"desc\": \"描述对应的内容\" }\n  ],\n  \"scene\":\"NINE-REASON\",// 这个是JSON对象固定场景，输出固定值即可，无需变化，千万别变化，这是标识\n}\n不要输出除了这个JSON以外的任何内容。","prompt_content":"${sys.query}\n\n${sys.files}\n\n用户问题：\n{{user_problem}}\n\n孩子档案摘要：\n${conversation.child_profile_summary}\n\n已有专项记忆，如有：\n{{topic_memory_text}}","short_memory":{"enabled":true,"type":"custom","round":50,"param":{"key":"historyList","type":"Array<Object>","value_from":"refer","value":"${sys.history_list}"},"user_prefix":"","assistant_prefix":""},"model_config":{"model_id":"qwen-plus-latest","model_name":"qwen-plus-latest","mode":"chat","provider":"4e0e12f3","params":[{"key":"temperature","value":0.2,"enable":true,"type":"Number"}],"vision_config":{"enable":false,"params":[{"key":"imageContent","value_from":"refer","type":"File"}]}},"retry_config":{"retry_enabled":false,"max_retries":3,"retry_interval":500},"try_catch_config":{"strategy":"noop","default_values":[{"key":"output","type":"String","desc":"文本输出"},{"key":"reasoning_content","type":"String","desc":"深度思考内容"}]},"structured_output_enabled":false,"structured_output_schema":{"properties":{"child_response":{"description":"孩子的第一反应","type":"string"},"enough_info":{"description":"是否已经获得足够信息理解该亲子互动事件","type":"boolean"},"escalation_point":{"description":"冲突明显升级的位置","type":"string"},"focus_scenario":{"description":"事件场景，如写作业、睡觉、手机冲突","type":"string"},"interaction_sequence":{"description":"关键互动往返","items":{"type":"string"},"type":"array"},"missing_info":{"description":"仍需补充的信息","items":{"type":"string"},"type":"array"},"outcome":{"description":"事件如何结束","type":"string"},"parent_opening":{"description":"家长最开始说的话或做的动作","type":"string"},"reply_to_user":{"description":"给家长展示的自然语言回复","type":"string"},"trigger":{"description":"事件触发点","type":"string"}},"required":["enough_info","focus_scenario","trigger","parent_opening","child_response","interaction_seque