e_focus = focus_match.group(1).strip()\n\n    situation = re.sub(r\"\\s+\", \" \", situation).strip()\n    practice_focus = re.sub(r\"\\s+\", \" \", practice_focus).strip()\n\n    scene_standard = f\"情境：{situation}\\n练习重点：{practice_focus}\"\n\n    return {\n        \"situation\": situation,\n        \"practice_focus\": practice_focus,\n        \"scene_standard\": scene_standard\n    }","script_type":"python","retry_config":{"retry_enabled":false,"max_retries":3,"retry_interval":500},"try_catch_config":{"strategy":"noop"},"imported_dify":{"code":"import re\n\ndef main(llm_output: str) -> dict:\n    text = llm_output.strip()\n\n    # 去掉 Markdown 加粗符号\n    text = text.replace(\"**\", \"\")\n\n    situation = \"\"\n    practice_focus = \"\"\n\n    situation_match = re.search(\n        r\"情境[:：]\\s*(.*?)(?=\\n\\s*练习重点[:：])\",\n        text,\n        flags=re.S\n    )\n    if situation_match:\n        situation = situation_match.group(1).strip()\n\n    focus_match = re.search(\n        r\"练习重点[:：]\\s*(.*?)(?=\\n\\s*(接下来你可以选一个方向|A\\.|A．|请回复|$))\",\n        text,\n        flags=re.S\n    )\n    if focus_match:\n        practice_focus = focus_match.group(1).strip()\n\n    situation = re.sub(r\"\\s+\", \" \", situation).strip()\n    practice_focus = re.sub(r\"\\s+\", \" \", practice_focus).strip()\n\n    scene_standard = f\"情境：{situation}\\n练习重点：{practice_focus}\"\n\n    return {\n        \"situation\": situation,\n        \"practice_focus\": practice_focus,\n        \"scene_standard\": scene_standard\n    }","code_language":"python3","outputs":{"practice_focus":{"type":"string"},"scene_standard":{"type":"string"},"situation":{"type":"string"}},"selected":false,"title":"代码执行 5","type":"code","variables":[{"value_selector":["1779249319750","text"],"value_type":"string","variable":"llm_output"}]}}}},{"id":"1779251426837","type":"Judge","name":"条件分支 4","desc":"","position":{"x":1790,"y":2385},"width":242,"config":{"input_params":[],"output_params":[],"node_param":{"branches":[{"