ocus}"}},{"id":"2","left":{"key":"","type":"String","value_from":"refer","value":"${conversation.scene_situation}"},"right":{"type":"String","value_from":"refer","value":"${1779257389763.scene_situation}"}}],"imported_dify":{"items":[{"input_type":"constant","operation":"set","value":"D","variable_selector":["conversation","stage"],"write_mode":"over-write"},{"input_type":"variable","operation":"over-write","value":["1779257389763","scene_practice_focus"],"variable_selector":["conversation","scene_practice_focus"],"write_mode":"over-write"},{"input_type":"variable","operation":"over-write","value":["1779257389763","scene_situation"],"variable_selector":["conversation","scene_situation"],"write_mode":"over-write"}],"selected":false,"title":"变量赋值 13 (1)","type":"assigner","version":"2"}}},"position":{"x":2474,"y":591},"width":242,"type":"VariableAssign"},{"id":"1779257389763","name":"代码执行 7","desc":"","config":{"input_params":[{"key":"llm_output","type":"String","value_from":"refer","value":"${1779251617824.output}"}],"output_params":[{"key":"scene_practice_focus","type":"String","desc":""},{"key":"scene_situation","type":"String","desc":""},{"key":"scene_standard","type":"String","desc":""}],"node_param":{"script_content":"import re\n\ndef main(llm_output: str) -> dict:\n    text = llm_output.strip()\n    text = text.replace(\"**\", \"\")\n\n    situation = \"\"\n    practice_focus = \"\"\n\n    # 提取情境\n    situation_match = re.search(\n        r\"情境[:：]\\s*(.*?)(?=\\n\\s*练习重点[:：]|$)\",\n        text,\n        flags=re.S\n    )\n    if situation_match:\n        situation = situation_match.group(1).strip()\n\n    # 提取练习重点\n    focus_match = re.search(\n        r\"练习重点[:：]\\s*(.*?)(?=\\n\\s*$|$)\",\n        text,\n        flags=re.S\n    )\n    if focus_match:\n        practice_focus = focus_match.group(1).strip()\n\n    # 清理多余空格和换行\n    situation = re.sub(r\"\\s+\", \" \", situation).strip()\n    practice_focus = re.sub(r\"\\s+\", \" \", practice_focus).strip()\n\n    scene_standard = f\"情境：{situation}\\n练习重点：{practice_focus}\"\n\n    return {\n        \"scene_situation\": situation,\n        \"scene_practice_focus\": practice_focus,\n        \"scene_standard\": scene_standard\n    }","script_type":"python","retry_config":{"retry_enabled":false,"max_retries":3,"retry_interval":500},"try_catch_config":{"strategy":"noop"},"imported_dify":{"code":"import re\n\ndef main(llm_output: str) -> dict:\n    text = llm_output.strip()\n    text = text.replace(\"**\", \"\")\n\n    situation = \"\"\n    practice_focus = \"\"\n\n    # 提取情境\n    situation_match = re.search(\n        r\"情境[:：]\\s*(.*?)(?=\\n\\s*练习重点[:：]|$)\",\n        text,\n        flags=re.S\n    )\n    if situation_match:\n        situation = situation_match.group(1).strip()\n\n    # 提取练习重点\n    focus_match = re.search(\n        r\"练习重点[:：]\\s*(.*?)(?=\\n\\s*$|$)\",\n        text,\n        flags=re.S\n    )\n    if focus_match:\n        practice_focus = focus_match.group(1).strip()\n\n    # 清理多余空格和换行\n    situation = re.sub(r\"\\s+\", \" \", situation).strip()\n    practice_focus = re.sub(r\"\\s+\", \" \", practice_focus).strip()\n\n    scene_standard = f\"情境：{situation}\\n练习重点：{practice_focus}\"\n\n    return {\n        \"scene_situation\": situation,\n        \"scene_practice_focus\": practice_focus,\n        \"scene_standard\": scene_standard\n    }","code_language":"python3","outputs":{"scene_practice_focus":{"type":"string"},"scene_situation":{"type":"string"},"scene_standard":{"type":"string"}},"selected":false,"title":"代码执行 7","type":"code","variables":[{"value_selector":["1779251617824","text"],"value_type":"string","variable":"llm_output"}]}}},"position":{"x":2112,"y":703},"width":242,"type":"Script"},{"id":"1779257888440","name":"代码执行 8","desc":"","config":{"input_params":[{"key":"llm_output","type":"String","value_from":"refer","value":"${1779251594986.output}"},{"key":"current_version","type":"String","value_from":"refer","value":"${conversation.plan_version}"},{"key":"old_revision_log","type":"String","value_from":"refer","value":"${conversation.plan_revision_log}"}],"output_params":[{"key":"plan_current_new","type":"String","desc":""},{"key":"plan_revision_log_new","type":"String","desc":""},{"key":"plan_revision_summary","type":"String","desc":""},{"key":"plan_version_new","type":"String","desc":""},{"key":"scene_practice_focus_new","type":"String","desc":""},{"key":"scene_situation_new","type":"String","desc":""},{"key":"scene_standard_new","type":"String","desc":""}],"node_param":{"script_content":"import re\n\ndef main(llm_output: str, current_version: str = \"1\", old_revision_log: str = \"\") -> dict:\n    text = llm_output.strip().replace(\"**\", \"\")\n\n    # 1. 提取修改说明\n    summary_match = re.search(\n        r\"【修改说明】\\s*(.*?)(?=\\n\\s*【更新后的完整方案】)\",\n        text,\n        flags=re.S\n    )\n    revision_summary = summary_match.group(1).strip() if summary_match else \"\"\n\n    # 2. 提取更新后的完整方案\n    plan_match = re.search(\n        r\"方案描述开始：\\s*(.*?)(?=\\n\\s*方案描述结束。|$)\",\n        text,\n        flags=re.S\n    )\n    plan_current_new = plan_match.group(1).strip() if plan_match else \"\"\n\n    # 3. 提取建议更新的模拟场景\n    scene_block_match = re.search(\n        r\"模拟场景描述开始：【建议更新的模拟场景】\\s*(.*)$\",\n        text,\n        flags=re.S\n    )\n    scene_block = scene_block_match.group(1).strip() if scene_block_match else \"\"\n\n    situation_match = re.search(\n        r\"情境[:：]\\s*(.*?)(?=\\n\\s*练习重点[:：]|$)\",\n        scene_block,\n        flags=re.S\n    )\n    focus_match = re.search(\n        r\"练习重点[:：]\\s*(.*?)(?=\\n\\s*$|$)\",\n        scene_block,\n        flags=re.S\n    )\n\n    scene_situation = situation_match.group(1).strip() if situation_match else \"\"\n    scene_practice_focus = focus_match.group(1).strip() if focus_match else \"\"\n\n    # 4. 清理空白\n    revision_summary = re.sub(r\"\\s+\", \" \", revision_summary).strip()\n    scene_situation = re.sub(r\"\\s+\", \" \", scene_situation).strip()\n    scene_practice_focus = re.sub(r\"\\s+\", \" \", scene_practice_focus).strip()\n\n    scene_standard = \"\"\n    if scene_situation or scene_practice_focus:\n        scene_standard = f\"情境：{scene_situation}\\n练习重点：{scene_practice_focus}\"\n\n    # 5. 版本号 +1\n    try:\n        new_version = int(current_version) + 1\n    except:\n        new_version = 2\n\n    # 6. 更新 revision log\n    new_log_entry = f\"v{new_version}：{revision_summary}\" if revision_summary else f\"v{new_version}：方案已根据家长补充进行修改。\"\n\n    if old_revision_log:\n        plan_revision_log = old_revision_log.strip() + \"\\n\" + new_log_entry\n    else:\n        plan_revision_log = new_log_entry\n\n    return {\n        \"plan_current_new\": plan_current_new,\n        \"plan_version_new\": str(new_version),\n        \"plan_revision_summary\": revision_summary,\n        \"plan_revision_log_new\": plan_revision_log,\n        \"scene_situation_new\": scene_situation,\n        \"scene_practice_focus_new\": scene_practice_focus,\n        \"scene_standard_new\": scene_standard\n    }","script_type":"python","retry_config":{"retry_enabled":false,"max_retries":3,"retry_interval":500},"try_catch_config":{"strategy":"noop"},"imported_dify":{"code":"import re\n\ndef main(llm_output: str, current_version: str = \"1\", old_revision_log: str = \"\") -> dict:\n    text = llm_output.strip().replace(\"**\", \"\")\n\n    # 1. 提取修改说明\n    summary_match = re.search(\n        r\"【修改说明】\\s*(.*?)(?=\\n\\s*【更新后的完整方案】)\",\n        text,\n        flags=re.S\n    )\n    revision_summary = summary_match.group(1).strip() if summary_match else \"\"\n\n    # 2. 提取更新后的完整方案\n    plan_match = re.search(\n        r\"方案描述开始：\\s*(.*?)(?=\\n\\s*方案描述结束。|$)\",\n        text,\n        flags=re.S\n    )\n    plan_current_new = plan_match.group(1).strip() if plan_match else \"\"\n\n    # 3. 提取建议更新的模拟场景\n    scene_block_match = re.search(\n        r\"模拟场景描述开始：【建议更新的模拟场景】\\s*(.*)$\",\n        text,\n        flags=re.S\n    )\n    scene_block = scene_block_match.group(1).strip() if scene_block_match else \"\"\n\n    situation_match = re.search(\n        r\"情境[:：]\\s*(.*?)(?=\\n\\s*练习重点[:：]|$)\",\n        scene_block,\n        flags=re.S\n    )\n    focus_match = re.search(\n        r\"练习重点[:：]\\s*(.*?)(?=\\n\\s*$|$)\",\n        scene_block,\n        flags=re.S\n    )\n\n    scene_situation = situation_match.group(1).strip() if situation_match else \"\"\n    scene_practice_focus = focus_match.group(1).strip() if focus_match else \"\"\n\n    # 4. 清理空白\n    revision_summary = re.sub(r\"\\s+\", \" \", revision_summary).strip()\n    scene_situation = re.sub(r\"\\s+\", \" \", scene_situation).strip()\n    scene_practice_focus = re.sub(r\"\\s+\", \" \", scene_practice_focus).strip()\n\n    scene_standard = \"\"\n    if scene_situation or scene_practice_focus:\n        scene_standard = f\"情境：{scene_situation}\\n练习重点：{scene_practice_focus}\"\n\n    # 5. 版本号 +1\n    try:\n        new_version = int(current_version) + 1\n    except:\n        new_version = 2\n\n    # 6. 更新 revision log\n    new_log_entry = f\"v{new_version}：{revision_summary}\" if revision_summary else f\"v{new_version}：方案已根据家长补充进行修改。\"\n\n    if old_revision_log:\n        plan_revision_log = old_revision_log.strip() + \"\\n\" + new_log_entry\n    else:\n        plan_revision_log = new_log_entry\n\n    return {\n        \"plan_current_new\": plan_current_new,\n        \"plan_version_new\": str(new_version),\n        \"plan_revision_summary\": revision_summary,\n        \"plan_revision_log_new\": plan_revision_log,\n        \"scene_situation_new\": scene_situation,\n        \"scene_practice_focus_new\": scene_practice_focus,\n        \"scene_standard_new\": scene_standard\n    }","code_language":"python3","outputs":{"plan_current_new":{"type":"string"},"plan_revision_log_new":{"type":"string"},"plan_revision_summary":{"type":"string"},"plan_version_new":{"type":"string"},"scene_practice_focus_new":{"type":"string"},"scene_situation_new":{"type":"string"},"scene_standard_new":{"type":"string"}},"selected":false,"title":"代码执行 8","type":"code","variables":[{"value_selector":["1779251594986","text"],"value_type":"string","variable":"llm_output"},{"value_selector":["conversation","plan_version"],"value_type":"string","variable":"current_version"},{"value_selector":["conversation","plan_revision_log"],"value_type":"string","variable":"old_revision_log"}]}}},"position":{"x":2112,"y":320},"width":242,"type":"Script"},{"id":"1779259944203","name":"变量赋值 17","desc":"","config":{"input_params":[],"output_params":[],"node_param":{"inputs":[{"id":"0","left":{"key":"","type":"String","value_from":"refer","value":"${conversation.stage}"},"right":{"type":"String","value_from":"input","value":"role_play"}},{"id":"1","left":{"key":"","type":"String","value_from":"refer","value":"${conversation.task_progress_score}"},"right":{"type":"String","value_from":"input","value":"0"}},{"id":"2","left":{"key":"","type":"String","value_from":"refer","value":"${conversation.child_mood_score}"},"right":{"type":"String","value_from":"input","value":"40"}},{"id":"3","left":{"key":"","type":"String","value_from":"refer","value":"${conversation.roleplay_last_child_response}"},"right":{"type":"String","value_from":"refer","value":"${1779179754877.output}"}},{"id":"4","left":{"key":"","type":"String","value_from":"refer","value":"${conversation.child_mood_state}"},"right":{"type":"String","value_from":"refer","value":"${1779260893635.child_mood_state}"}},{"id":"5","left":{"key":"","type":"String","value_from":"refer","value":"${conversation.child_inner_thought}"},"right":{"type":"String","value_from":"refer","value":"${1779260893635.child_inner_thought}"}},{"id":"6","left":{"key":"","type":"String","value_from":"refer","value":"${conversation.roleplay_turn_count}"},"right":{"type":"String","value_from":"input","value":"1"}},{"id":"7","left":{"key":"","type":"Boolean","value_from":"refer","value":"${conversation.roleplay_started}"},"right":{"type":"Boolean","value_from":"input","value":true}}],"imported_dify":{"items":[{"input_type":"constant","operation":"set","value":"role_play","variable_selector":["conversation","stage"],"write_mode":"over-write"},{"input_type":"constant","operation":"set","value":"0","variable_selector":["conversation","task_progress_score"],"write_mode":"over-write"},{"input_type":"constant","operation":"set","value":"40","variable_selector":["conversation","child_mood_score"],"write_mode":"over-write"},{"input_type":"variable","operation":"over-write","value":["1779179754877","text"],"variable_selector":["conversation","roleplay_last_child_response"],"write_mode":"over-write"},{"input_type":"variable","operation":"over-write","value":["1779260893635","child_mood_state"],"variable_selector":["conversation","child_mood_state"],"write_mode":"over-write"},{"input_type":"variable","operation":"over-write","value":["1779260893635","child_inner_thought"],"variable_selector":["conversation","child_inner_thought"],"write_mode":"over-write"},{"input_type":"constant","operation":"set","value":"1","variable_selector":["conversation","roleplay_turn_count"],"write_mode":"over-write"},{"input_type":"constant","operation":"set","value":true,"variable_selector":["conversation","roleplay_started"],"write_mode":"over-write"}],"selected":false,"title":"变量赋值 17","type":"assigner","version":"2"}}},"position":{"x":3178,"y":2441},"width":242,"type":"VariableAssign"},{"id":"1779259977084","name":"LLM 模拟对练","desc":"","config":{"input_params":[],"output_params":[{"key":"output","type":"String","desc":"文本输出"},{"key":"reasoning_content","type":"String","desc":"深度思考内容"}],"node_param":{"sys_prompt_content":"你是一个亲子沟通训练教练 + 孩子角色扮演者。\n\n你有两个身份：\n1. 孩子：根据当前情境、孩子特点和上一轮对话做出自然反应。\n2. 教练：根据家长本轮回应，评估家长是否完成了本轮练习重点，并给出简短反馈。\n\n你必须先读取当前训练任务：\n\n你的任务不是每轮重新打分，而是根据家长本轮表现，对“孩子心情”和“任务进度”分别做加分或减分。\n\n孩子心情表示：孩子此刻的情绪状态、防御程度和愿意继续说话的程度。\n任务进度表示：家长是否完成当前练习重点。\n\n两个分数范围都是0-100分。\n\n一、孩子心情评分规则：\n\n+20：家长准确接住孩子情绪，没有压迫，并让孩子感觉被理解。\n+10：家长语气平稳，没有继续升级，也有基本理解。\n0：家长没有明显伤害沟通，但也没有让孩子更放松。\n-10：家长说教、反问、追问过急、否定孩子感受。\n-20：家长威胁、羞辱、贴标签、翻旧账、强压孩子。\n\n孩子心情会影响孩子下一轮回应：\n0-20：孩子强烈防御，可能拒绝沟通、顶撞、离开。\n21-40：孩子不耐烦、防御、敷衍。\n41-60：孩子仍有防御，但可以短句回应。\n61-80：孩子情绪缓和，愿意说一点真实想法。\n81-100：孩子明显放松，愿意继续谈一个具体问题，但不代表问题完全解决。\n\n注意：\n孩子心情不要因为一次普通配合就快速升到100。\n在规则、学习、手机、外出、风险核实等场景中，即使孩子愿意尝试，也通常仍会有一点不情愿、试探或保留。\n除非家长连续多轮回应非常好，且孩子已经明确表现出放松和主动合作，否则孩子心情不要轻易超过85。\n\n二、任务进度评分规则：\n\n任务进度必须严格根据“练习重点”判断，而不是根据孩子是否配合、家长语气是否温和来判断。\n\n孩子心情和任务进度是两个不同维度：\n- 家长说得温和，可能让孩子心情上升，但如果没有推进练习重点，任务进度只能小幅增加或不增加。\n- 家长守住边界，可能让孩子心情短期下降，但如果完成了练习重点，任务进度可以增加。\n- 不能因为孩子答应了、语气软化了，就自动提高任务进度。\n- 不能因为家长提出了吃东西、换时间、聊一聊等低压力安排，就自动认为练习目标完成。\n\n+25：家长很好地完成当前练习重点，并且表达自然、具体，如果孩子已经给出相对负责的安排，家长能及时肯定并把它整理成规则或标准。\n+15：家长基本完成练习重点，但还可以更短、更清楚。\n+5：家长有一点接近练习重点，但比较空泛或不完整。\n0：没有推进当前练习重点。\n-10：明显偏离练习重点，或让冲突升级，或孩子已经给出相对负责的安排，如果家长继续追问细节，尤其是与练习重点无关的隐私或内容，任务进度不应继续明显增加，孩子心情可能下降。\n\n请根据不同练习重点判断任务完成度：\n你必须根据“练习重点”的关键词和含义判断，而不是套用固定模板。\n\n- 如果练习重点是暂停冲突：看家长有没有停止当场拉扯，并为后续沟通留下入口。\n- 如果练习重点是规则协商：看家长有没有说清规则、选择和后果。\n- 如果练习重点是风险核实：看家长有没有核实具体行为，而不是直接骂人、禁止或羞辱。\n- 如果练习重点是心理状态支持：看家长有没有减少指责、表达担心，并提供低压力支持。\n- 如果练习重点是能力训练：看家长有没有把任务拆小，而不是把问题说成态度差。\n- 如果练习重点是回避压力：看家长有没有降低启动难度，而不是只催促或只用奖励。\n- 如果练习重点是即时满足管理：看家长有没有减少诱惑暴露、提前约定、设置结束点，而不是只讲道理。\n\n三、孩子反应规则：\n\n1. 孩子的下一句话必须与当前孩子心情分数匹配。\n2. 孩子反应必须自然延续上一轮孩子回应和家长本轮回应。\n3. 不要为了推进任务而突然让孩子大幅转变态度。\n4. 如果孩子改变想法，需要有合理过渡。\n5. 孩子说话要口语化。\n6. 单次孩子回复控制在50字以内。\n7. 不要让孩子立刻完全配合。\n8. 不要过度戏剧化。\n9. 不要加入当前情境没有的新严重风险。\n10. 如果家长回应很好，孩子可以稍微软化，但仍可保留一点别扭、试探或不情愿。\n\n四、孩子内在心理活动：\n\n你需要用一句话说明孩子心里可能在想什么。\n要求：\n- 用“孩子心里可能在想：……”开头。\n- 不要过度解读。\n- 不要超过30字。\n- 要帮助家长理解孩子为什么这样反应。\n\n五、反馈规则：\n\n反馈必须简短，最多2句话。\n要说明：\n- 家长这轮做得好或不好的一个关键点；\n- 为什么会让孩子更愿意说，或更防御；\n- 用“你”指代家长；\n- 用“孩子”指代孩子。\n\n如果任务进度增加明显，反馈以肯定为主。\n如果孩子心情下降或任务进度没有推进，要指出一个最主要问题。\n\n六、示范/小提示规则：\n\n小提示和示范必须严格服务当前练习重点。\n不要给和练习重点无关的建议。\n不要建议买零食、吃水果、送东西、讲趣事、制造仪式感、营造氛围，除非家长原本提到这种家庭习惯。\n不要把所有问题都引向“再聊聊”“更温柔一点”“多陪伴”。\n不要为了推进对话而不断追问孩子隐私或细节。\n\n如果孩子心情变化为负分，或任务进度为0/负分，必须给“示范”。\n示范要给一句现实家长能说出口的话。\n\n如果孩子心情变化为正分，且任务进度也增加，则不给完整示范，只给“小提示”。\n小提示要告诉家长下一句可以如何继续推进练习重点。\n\n如果孩子已经表现出相对负责的行为，不要继续提示家长追问更多细节。\n此时小提示应引导家长：\n1. 肯定孩子已经做对的部分；\n2. 总结有效经验；\n3. 明确可以继续执行的规则；\n4. 保留必要底线；\n5. 结束或收束本轮谈话。\n\n“已经相对负责”的表现包括：\n- 已经完成任务或能说明完成安排；\n- 能说出时间安排；\n- 能考虑学习、睡眠、上课状态、安全或规则影响；\n- 能说明基本安全信息；\n- 能表达拒绝、求助或保护自己的意识；\n- 能提出可执行安排；\n- 愿意接受部分规则或协商。\n\n如果当前进度已经达到70以上，且孩子已经给出基本信息或可执行安排，小提示应优先引导家长收束对话，而不是继续扩展追问。\n\n示范必须满足：\n- 聚焦当前情境；\n- 符合当前练习重点；\n- 不羞辱、不威胁、不讲大道理；\n- 如果重点是暂停冲突，就示范如何暂停和约定复谈；\n- 如果重点是规则协商，就示范如何说清规则、选择和后果；\n- 如果重点是风险核实，就示范如何问具体行为和安全底线；\n- 如果重点是心理支持，就示范如何表达观察、担心和支持；\n- 如果重点是能力训练，就示范如何拆小步骤；\n- 如果重点是回避压力，就示范如何降低启动难度；\n- 如果重点是即时满足管理，就示范如何设置结束点和减少诱惑暴露；\n- 如果孩子已经表现负责，就示范如何肯定、总结经验、明确规则并停止追问；\n- 不要太油腻；\n- 不要像心理咨询师讲课。\n\n七、当孩子已经表现得相对负责时，不要继续追问\n\n如果孩子的回应显示他/她已经在某方面做得比较负责，教练反馈、小提示和示范不能继续鼓励家长追问更多细节。\n\n“已经比较负责”的表现包括但不限于：\n- 已经完成作业或能说明自己的完成安排；\n- 能说出大致时间安排；\n- 能考虑睡眠、学习、上课状态或规则影响；\n- 能说明外出地点、回家时间、同行者等基本安全信息；\n- 能表达自己有拒绝、求助、保护自己的意识；\n- 能主动提出一个可执行的安排；\n- 能接受部分规则或愿意协商；\n- 能说明自己正在尝试调整。\n\n在这种情况下，家长的下一步不应是继续追问，而应是：\n1. 先肯定孩子已经做对的部分；\n2. 帮孩子总结这个做法为什么有效；\n3. 把可继续执行的规则或标准说清楚；\n4. 只保留必要底线；\n5. 停止过度追问细节，避免把好不容易打开的沟通重新变成审问。\n\n此时任务进度评分应这样判断：\n- 如果家长能及时肯定孩子已有的负责行为，并把经验总结成清楚规则，任务进度可以明显增加。\n- 如果家长在孩子已经表现负责后仍继续追问隐私、细节或动机，孩子心情应下降，任务进度不应明显增加。\n- 如果家长只说“不错”“挺好”，但没有总结规则或标准，任务进度只能小幅增加。\n- 如果家长把孩子的负责表现继续当成审问入口，任务进度为0或下降。\n\n小提示和示范也必须遵守：\n- 不要在孩子已经回答得比较负责时继续建议追问更多细节。\n- 应提示家长把谈话收束为肯定 + 规则 + 后续约定。\n- 不要为了推进对话而不断制造新问题。\n\n八、输出格式：\n请先按照如下格式组织输出内容的逻辑：\n你只能严格按顺序组织以下部分，不要输出其他标题、解释或评分过程：\n\n孩子：________。\n\n孩子状态：________、________｜心情变化：___，当前心情：___｜任务进度：___，当前进度：___\n\n孩子心里可能在想：________。\n\n反馈：________。\n\n小提示：________。\n或\n示范：________。\n真正输出的时候请严格按照如下的JSON格式输出内容：\n{\n  \"child_dialogue\": \"【孩子在当前场景下的具体回应。】\",\n  \"state_metrics\": {\n    \"status\": [\"状态1\", \"状态2\"],\n    \"mood_change\": \"心情数值变化，如 +10\",// 要是字符串，不是数字\n    \"current_mood\": \"当前心情数值，如 60\",\n    \"task_progress\": \"任务进度变化，如 0\",\n    \"current_progress\": \"当前总进度，如 15\"\n  },\n  \"child_internal_thought\": \"【孩子此时心里的真实想法。】\",\n  \"feedback\": \"【家长上一轮操作后的即时反馈，客观评价其对孩子心理和任务的影响。】\",\n  \"suggestion_or_demo\": {\n    \"type\": \"tip\" | \"demo\",\n    \"content\": \"给家长的具体小提示，或话术示范。\"\n  },\n\"scene\":\"MLGC\",// 这个是JSON对象固定场景，输出固定值即可，无需变化，千万别变化，这是标识\n}\n【严格的 JSON 格式输出要求】\n你必须输出标准、合法的 JSON 格式。所有的键（Key）和字符串值（Value）的外层必须使用标准的英文双引号 \"\" 包裹。\n⚠️ 致命红线：为了防止 JSON 解析崩溃，在任何字符串的内部（例如对话、内心想法等），绝对禁止使用任何形式的双引号（包括中文双引号“”和英文双引号\"\"）！\n如果你需要引用对话或强调某些词，请一律使用方括号【 】或者直角引号「 」来代替。\n参考示例： ⛔ 错误: {\"content\": \"妈妈问：\"今天开心吗？\"\"} ✅ 正确: {\"content\": \"妈妈问：【今天开心吗？】\"}\n除了这个JSON，不要输出额外的任何内容。","prompt_content":"当前有效方案：\n${conversation.plan_current}\n\n情境：\n${conversation.scene_situation}\n\n练习重点：\n${conversation.scene_practice_focus}\n\n孩子特点：\n${conversation.child_profile_summary}\n\n孩子上一轮回应：\n${conversation.roleplay_last_child_response}\n\n家长本轮回应：\n${sys.query}\n\n上一轮孩子心情：\n${conversation.child_mood_score}\n\n上一轮任务进度：\n${conversation.task_progress_score}","short_memory":{"enabled":true,"type":"custom","round":50,"param":{"key":"historyList","type":"Array<Object>","value_from":"refer","value":"${sys.history_list}"},"user_prefix":"","assistant_prefix":""},"model_config":{"model_id":"qwen-plus-latest","model_name":"qwen-plus-latest","mode":"chat","provider":"4e0e12f3","params":[{"key":"temperature","value":0.7,"enable":true,"type":"Number"}],"vision_config":{"enable":false,"params":[{"key":"imageContent","value_from":"refer","type":"File"}]}},"retry_config":{"retry_enabled":false,"max_retries":3,"retry_interval":500},"try_catch_config":{"strategy":"noop","default_values":[{"key":"output","type":"String","desc":"文本输出"},{"key":"reasoning_content","type":"String","desc":"深度思考内容"}]},"structured_output_enabled":false,"structured_output_schema":{"type":"object","properties":{},"required":[],"additionalProperties":false},"imported_dify":{"context":{"enabled":false,"variable_selector":[]},"memory":{"query_prompt_template":"当前有效方案：\n{{#conversation.plan_current#}}\n\n情境：\n{{#conversation.scene_situation#}}\n\n练习重点：\n{{#conversation.scene_practice_focus#}}\n\n孩子特点：\n{{#conversation.child_profile_summary#}}\n\n孩子上一轮回应：\n{{#conversation.roleplay_last_child_response#}}\n\n家长本轮回应：\n{{#sys.query#}}\n\n上一轮孩子心情：\n{{#conversation.child_mood_score#}}\n\n上一轮任务进度：\n{{#conversation.task_progress_score#}}","role_prefix":{"assistant":"","user":""},"window":{"enabled":false,"size":50}},"model":{"completion_params":{"temperature":0.7},"mode":"chat","name":"qwen-plus-latest","provider":"langgenius/tongyi/tongyi"},"prompt_template":[{"id":"ac31ce52-b93f-4d50-ade3-0eae8e17fc17","role":"system","text":"你是一个亲子沟通训练教练 + 孩子角色扮演者。\n\n你有两个身份：\n1. 孩子：根据当前情境、孩子特点和上一轮对话做出自然反应。\n2. 教练：根据家长本轮回应，评估家长是否完成了本轮练习重点，并给出简短反馈。\n\n你必须先读取当前训练任务：\n\n你的任务不是每轮重新打分，而是根据家长本轮表现，对“孩子心情”和“任务进度”分别做加分或减分。\n\n孩子心情表示：孩子此刻的情绪状态、防御程度和愿意继续说话的程度。\n任务进度表示：家长是否完成当前练习重点。\n\n两个分数范围都是0-100分。\n\n一、孩子心情评分规则：\n\n+20：家长准确接住孩子情绪，没有压迫，并让孩子感觉被理解。\n+10：家长语气平稳，没有继续升级，也有基本理解。\n0：家长没有明显伤害沟通，但也没有让孩子更放松。\n-10：家长说教、反问、追问过急、否定孩子感受。\n-20：家长威胁、羞辱、贴标签、翻旧账、强压孩子。\n\n孩子心情会影响孩子下一轮回应：\n0-20：孩子强烈防御，可能拒绝沟通、顶撞、离开。\n21-40：孩子不耐烦、防御、敷衍。\n41-60：孩子仍有防御，但可以短句回应。\n61-80：孩子情绪缓和，愿意说一点真实想法。\n81-100：孩子明显放松，愿意继续谈一个具体问题，但不代表问题完全解决。\n\n注意：\n孩子心情不要因为一次普通配合就快速升到100。\n在规则、学习、手机、外出、风险核实等场景中，即使孩子愿意尝试，也通常仍会有一点不情愿、试探或保留。\n除非家长连续多轮回应非常好，且孩子已经明确表现出放松和主动合作，否则孩子心情不要轻易超过85。\n\n二、任务进度评分规则：\n\n任务进度必须严格根据“练习重点”判断，而不是根据孩子是否配合、家长语气是否温和来判断。\n\n孩子心情和任务进度是两个不同维度：\n- 家长说得温和，可能让孩子心情上升，但如果没有推进练习重点，任务进度只能小幅增加或不增加。\n- 家长守住边界，可能让孩子心情短期下降，但如果完成了练习重点，任务进度可以增加。\n- 不能因为孩子答应了、语气软化了，就自动提高任务进度。\n- 不能因为家长提出了吃东西、换时间、聊一聊等低压力安排，就自动认为练习目标完成。\n\n+25：家长很好地完成当前练习重点，并且表达自然、具体，如果孩子已经给出相对负责的安排，家长能及时肯定并把它整理成规则或标准。\n+15：家长基本完成练习重点，但还可以更短、更清楚。\n+5：家长有一点接近练习重点，但比较空泛或不完整。\n0：没有推进当前练习重点。\n-10：明显偏离练习重点，或让冲突升级，或孩子已经给出相对负责的安排，如果家长继续追问细节，尤其是与练习重点无关的隐私或内容，任务进度不应继续明显增加，孩子心情可能下降。\n\n请根据不同练习重点判断任务完成度：\n你必须根据“练习重点”的关键词和含义判断，而不是套用固定模板。\n\n- 如果练习重点是暂停冲突：看家长有没有停止当场拉扯，并为后续沟通留下入口。\n- 如果练习重点是规则协商：看家长有没有说清规则、选择和后果。\n- 如果练习重点是风险核实：看家长有没有核实具体行为，而不是直接骂人、禁止或羞辱。\n- 如果练习重点是心理状态支持：看家长有没有减少指责、表达担心，并提供低压力支持。\n- 如果练习重点是能力训练：看家长有没有把任务拆小，而不是把问题说成态度差。\n- 如果练习重点是回避压力：看家长有没有降低启动难度，而不是只催促或只用奖励。\n- 如果练习重点是即时满足管理：看家长有没有减少诱惑暴露、提前约定、设置结束点，而不是只讲道理。\n\n三、孩子反应规则：\n\n1. 孩子的下一句话必须与当前孩子心情分数匹配。\n2. 孩子反应必须自然延续上一轮孩子回应和家长本轮回应。\n3. 不要为了推进任务而突然让孩子大幅转变态度。\n4. 如果孩子改变想法，需要有合理过渡。\n5. 孩子说话要口语化。\n6. 单次孩子回复控制在50字以内。\n7. 不要让孩子立刻完全配合。\n8. 不要过度戏剧化。\n9. 不要加入当前情境没有的新严重风险。\n10. 如果家长回应很好，孩子可以稍微软化，但仍可保留一点别扭、试探或不情愿。\n\n四、孩子内在心理活动：\n\n你需要用一句话说明孩子心里可能在想什么。\n要求：\n- 用“孩子心里可能在想：……”开头。\n- 不要过度解读。\n- 不要超过30字。\n- 要帮助家长理解孩子为什么这样反应。\n\n五、反馈规则：\n\n反馈必须简短，最多2句话。\n要说明：\n- 家长这轮做得好或不好的一个关键点；\n- 为什么会让孩子更愿意说，或更防御；\n- 用“你”指代家长；\n- 用“孩子”指代孩子。\n\n如果任务进度增加明显，反馈以肯定为主。\n如果孩子心情下降或任务进度没有推进，要指出一个最主要问题。\n\n六、示范/小提示规则：\n\n小提示和示范必须严格服务当前练习重点。\n不要给和练习重点无关的建议。\n不要建议买零食、吃水果、送东西、讲趣事、制造仪式感、营造氛围，除非家长原本提到这种家庭习惯。\n不要把所有问题都引向“再聊聊”“更温柔一点”“多陪伴”。\n不要为了推进对话而不断追问孩子隐私或细节。\n\n如果孩子心情变化为负分，或任务进度为0/负分，必须给“示范”。\n示范要给一句现实家长能说出口的话。\n\n如果孩子心情变化为正分，且任务进度也增加，则不给完整示范，只给“小提示”。\n小提示要告诉家长下一句可以如何继续推进练习重点。\n\n如果孩子已经表现出相对负责的行为，不要继续提示家长追问更多细节。\n此时小提示应引导家长：\n1. 肯定孩子已经做对的部分；\n2. 总结有效经验；\n3. 明确可以继续执行的规则；\n4. 保留必要底线；\n5. 结束或收束本轮谈话。\n\n“已经相对负责”的表现包括：\n- 已经完成任务或能说明完成安排；\n- 能说出时间安排；\n- 能考虑学习、睡眠、上课状态、安全或规则影响；\n- 能说明基本安全信息；\n- 能表达拒绝、求助或保护自己的意识；\n- 能提出可执行安排；\n- 愿意接受部分规则或协商。\n\n如果当前进度已经达到70以上，且孩子已经给出基本信息或可执行安排，小提示应优先引导家长收束对话，而不是继续扩展追问。\n\n示范必须满足：\n- 聚焦当前情境；\n- 符合当前练习重点；\n- 不羞辱、不威胁、不讲大道理；\n- 如果重点是暂停冲突，就示范如何暂停和约定复谈；\n- 如果重点是规则协商，就示范如何说清规则、选择和后果；\n- 如果重点是风险核实，就示范如何问具体行为和安全底线；\n- 如果重点是心理支持，就示范如何表达观察、担心和支持；\n- 如果重点是能力训练，就示范如何拆小步骤；\n- 如果重点是回避压力，就示范如何降低启动难度；\n- 如果重点是即时满足管理，就示范如何设置结束点和减少诱惑暴露；\n- 如果孩子已经表现负责，就示范如何肯定、总结经验、明确规则并停止追问；\n- 不要太油腻；\n- 不要像心理咨询师讲课。\n\n七、当孩子已经表现得相对负责时，不要继续追问\n\n如果孩子的回应显示他/她已经在某方面做得比较负责，教练反馈、小提示和示范不能继续鼓励家长追问更多细节。\n\n“已经比较负责”的表现包括但不限于：\n- 已经完成作业或能说明自己的完成安排；\n- 能说出大致时间安排；\n- 能考虑睡眠、学习、上课状态或规则影响；\n- 能说明外出地点、回家时间、同行者等基本安全信息；\n- 能表达自己有拒绝、求助、保护自己的意识；\n- 能主动提出一个可执行的安排；\n- 能接受部分规则或愿意协商；\n- 能说明自己正在尝试调整。\n\n在这种情况下，家长的下一步不应是继续追问，而应是：\n1. 先肯定孩子已经做对的部分；\n2. 帮孩子总结这个做法为什么有效；\n3. 把可继续执行的规则或标准说清楚；\n4. 只保留必要底线；\n5. 停止过度追问细节，避免把好不容易打开的沟通重新变成审问。\n\n此时任务进度评分应这样判断：\n- 如果家长能及时肯定孩子已有的负责行为，并把经验总结成清楚规则，任务进度可以明显增加。\n- 如果家长在孩子已经表现负责后仍继续追问隐私、细节或动机，孩子心情应下降，任务进度不应明显增加。\n- 如果家长只说“不错”“挺好”，但没有总结规则或标准，任务进度只能小幅增加。\n- 如果家长把孩子的负责表现继续当成审问入口，任务进度为0或下降。\n\n小提示和示范也必须遵守：\n- 不要在孩子已经回答得比较负责时继续建议追问更多细节。\n- 应提示家长把谈话收束为肯定 + 规则 + 后续约定。\n- 不要为了推进对话而不断制造新问题。\n\n八、输出格式：\n请先按照如下格式组织输出内容的逻辑：\n你只能严格按顺序组织以下部分，不要输出其他标题、解释或评分过程：\n\n孩子：________。\n\n孩子状态：________、________｜心情变化：___，当前心情：___｜任务进度：___，当前进度：___\n\n孩子心里可能在想：________。\n\n反馈：________。\n\n小提示：________。\n或\n示范：________。\n真正输出的时候请严格按照如下的JSON格式输出内容：\n{\n  \"child_dialogue\": \"【孩子在当前场景下的具体回应。】\",\n  \"state_metrics\": {\n    \"status\": [\"状态1\", \"状态2\"],\n    \"mood_change\": \"心情数值变化，如 +10\",// 要是字符串，不是数字\n    \"current_mood\": \"当前心情数值，如 60\",\n    \"task_progress\": \"任务进度变化，如 0\",\n    \"current_progress\": \"当前总进度，如 15\"\n  },\n  \"child_internal_thought\": \"【孩子此时心里的真实想法。】\",\n  \"feedback\": \"【家长上一轮操作后的即时反馈，客观评价其对孩子心理和任务的影响。】\",\n  \"suggestion_or_demo\": {\n    \"type\": \"tip\" | \"demo\",\n    \"content\": \"给家长的具体小提示，或话术示范。\"\n  },\n\"scene\":\"MLGC\",// 这个是JSON对象固定场景，输出固定值即可，无需变化，千万别变化，这是标识\n}\n【严格的 JSON 格式输出要求】\n你必须输出标准、合法的 JSON 格式。所有的键（Key）和字符串值（Value）的外层必须使用标准的英文双引号 \"\" 包裹。\n⚠️ 致命红线：为了防止 JSON 解析崩溃，在任何字符串的内部（例如对话、内心想法等），绝对禁止使用任何形式的双引号（包括中文双引号“”和英文双引号\"\"）！\n如果你需要引用对话或强调某些词，请一律使用方括号【 】或者直角引号「 」来代替。\n参考示例： ⛔ 错误: {\"content\": \"妈妈问：\"今天开心吗？\"\"} ✅ 正确: {\"content\": \"妈妈问：【今天开心吗？】\"}\n除了这个JSON，不要输出额外的任何内容。"}],"selected":false,"title":"LLM 模拟对练","type":"llm","vision":{"enabled":false}}}},"position":{"x":1428,"y":949.4285714285713},"width":242,"type":"LLM"},{"id":"1779260893635","name":"代码执行 9","desc":"","config":{"input_params":[{"key":"llm_output","type":"String","value_from":"refer","value":"${1779179754877.output}"}],"output_params":[{"key":"child_inner_thought","type":"String","desc":""},{"key":"child_mood_score","type":"String","desc":""},{"key":"child_mood_state","type":"String","desc":""},{"key":"child_response","type":"String","desc":""},{"key":"task_progress_score","type":"String","desc":""}],"node_param":{"script_content":"import re\n\ndef main(llm_output: str) -> dict:\n    text = llm_output.strip().replace(\"**\", \"\")\n\n    child_response = \"\"\n    child_mood_state = \"\"\n    child_mood_score = \"40\"\n    task_progress_score = \"0\"\n    child_inner_thought = \"\"\n\n    child_match = re.search(\n        r\"孩子[:：]\\s*(.*?)(?=\\n\\s*孩子状态[:：])\",\n        text,\n        flags=re.S\n    )\n    if child_match:\n        child_response = child_match.group(1).strip()\n\n    state_match = re.search(\n        r\"孩子状态[:：]\\s*(.*?)｜当前心情[:：]\\s*([0-9]+)\\s*｜当前进度[:：]\\s*([0-9]+)\",\n        text,\n        flags=re.S\n    )\n    if state_match:\n        child_mood_state = state_match.group(1).strip()\n        child_mood_score = state_match.group(2).strip()\n        task_progress_score = state_match.group(3).strip()\n\n    thought_match = re.search(\n        r\"孩子心里可能在想[:：]\\s*(.*?)(?=\\n\\s*请你以家长身份回应|$)\",\n        text,\n        flags=re.S\n    )\n    if thought_match:\n        child_inner_thought = thought_match.group(1).strip()\n\n    child_response = re.sub(r\"\\s+\", \" \", child_response).strip()\n    child_mood_state = re.sub(r\"\\s+\", \" \", child_mood_state).strip()\n    child_inner_thought = re.sub(r\"\\s+\", \" \", child_inner_thought).strip()\n\n    return {\n        \"child_response\": child_response,\n        \"child_mood_state\": child_mood_state,\n        \"child_mood_score\": child_mood_score,\n        \"task_progress_score\": task_progress_score,\n        \"child_inner_thought\": child_inner_thought\n    }","script_type":"python","retry_config":{"retry_enabled":false,"max_retries":3,"retry_interval":500},"try_catch_config":{"strategy":"noop"},"imported_dify":{"code":"import re\n\ndef main(llm_output: str) -> dict:\n    text = llm_output.strip().replace(\"**\", \"\")\n\n    child_response = \"\"\n    child_mood_state = \"\"\n    child_mood_score = \"40\"\n    task_progress_score = \"0\"\n    child_inner_thought = \"\"\n\n    child_match = re.search(\n        r\"孩子[:：]\\s*(.*?)(?=\\n\\s*孩子状态[:：])\",\n        text,\n        flags=re.S\n    )\n    if child_match:\n        child_response = child_match.group(1).strip()\n\n    state_match = re.search(\n        r\"孩子状态[:：]\\s*(.*?)｜当前心情[:：]\\s*([0-9]+)\\s*｜当前进度[:：]\\s*([0-9]+)\",\n        text,\n        flags=re.S\n    )\n    if state_match:\n        child_mood_state = state_match.group(1).strip()\n        child_mood_score = state_match.group(2).strip()\n        task_progress_score = state_match.group(3).strip()\n\n    thought_match = re.search(\n        r\"孩子心里可能在想[:：]\\s*(.*?)(?=\\n\\s*请你以家长身份回应|$)\",\n        text,\n        flags=re.S\n    )\n    if thought_match:\n        child_inner_thought = thought_match.group(1).strip()\n\n    child_response = re.sub(r\"\\s+\", \" \", child_response).strip()\n    child_mood_state = re.sub(r\"\\s+\", \" \", child_mood_state).strip()\n    child_inner_thought = re.sub(r\"\\s+\", \" \", child_inner_thought).strip()\n\n    return {\n        \"child_response\": child_response,\n        \"child_mood_state\": child_mood_state,\n        \"child_mood_score\": child_mood_score,\n        \"task_progress_score\": task_progress_score,\n        \"child_inner_thought\": child_inner_thought\n    }","code_language":"python3","outputs":{"child_inner_thought":{"type":"string"},"child_mood_score":{"type":"string"},"child_mood_state":{"type":"string"},"child_response":{"type":"string"},"task_progress_score":{"type":"string"}},"selected":false,"title":"代码执行 9","type":"code","variables":[{"value_selector":["1779179754877","text"],"value_type":"string","variable":"llm_output"}]}}},"position":{"x":2836,"y":2548},"width":242,"type":"Script"},{"id":"1779261846938","name":"直接回复 11","desc":"","config":{"input_params":[],"output_params":[],"node_param":{"output":"${1779259977084.output}","stream_switch":true,"imported_dify":{"answer":"{{#1779259977084.text#}}","selected":false,"title":"直接回复 11","type":"answer","variables":[]}}},"position":{"x":1770,"y":940},"width":242,"type":"Output"},{"id":"1779261854909","name":"代码执行 10","desc":"","config":{"input_params":[{"key":"llm_output","type":"String","value_from":"refer","value":"${1779259977084.output}"}],"output_params":[{"key":"child_inner_thought","type":"String","desc":""},{"key":"child_mood_delta","type":"String","desc":""},{"key":"child_mood_score","type":"String","desc":""},{"key":"child_mood_state","type":"String","desc":""},{"key":"child_response","type":"String","desc":""},{"key":"coach_feedback","type":"String","desc":""},{"key":"coach_output_type","type":"String","desc":""},{"key":"coach_tip_or_demo","type":"String","desc":""},{"key":"stage_next","type":"String","desc":""},{"key":"task_completed","type":"String","desc":""},{"key":"task_progress_delta","type":"String","desc":""},{"key":"task_progress_score","type":"String","desc":""}],"node_param":{"script_content":"import json\n\ndef clamp_score(value: int, min_value: int = 0, max_value: int = 100) -> int:\n    return max(min_value, min(max_value, value))\n\ndef main(llm_output: str) -> dict:\n    # 1. 安全解析 JSON\n    try:\n        # 如果模型偶尔带上 ```json ... ``` 包裹，需要做一点清理\n        cleaned_json = llm_output.strip().replace(\"```json\", \"\").replace(\"```\", \"\")\n        data = json.loads(cleaned_json)\n    except json.JSONDecodeError:\n        # 处理解析失败的情况，返回默认值或抛出错误\n        return {\"error\": \"Invalid JSON format\"}\n\n    # 2. 从字典中获取数据 (使用 get 提供默认值)\n    metrics = data.get(\"state_metrics\", {})\n    suggestion = data.get(\"suggestion_or_demo\", {})\n\n    mood_score_int = clamp_score(int(metrics.get(\"current_mood\", 40)))\n    progress_score_int = clamp_score(int(metrics.get(\"current_progress\", 0)))\n\n    # 3. 逻辑判定\n    task_completed = \"true\" if progress_score_int >= 100 else \"false\"\n    stage_next = \"roleplay_summary\" if task_completed == \"true\" else \"role_play\"\n\n    # 4. 组装返回字典\n    return {\n        \"child_response\": data.get(\"child_dialogue\", \"\"),\n        \"child_mood_state\": \", \".join(metrics.get(\"status\", [])),\n        \"child_mood_delta\": str(metrics.get(\"mood_change\", \"0\")),\n        \"child_mood_score\": str(mood_score_int),\n        \"task_progress_delta\": str(metrics.get(\"task_progress\", \"0\")),\n        \"task_progress_score\": str(progress_score_int),\n        \"task_completed\": task_completed,\n        \"stage_next\": stage_next,\n        \"child_inner_thought\": data.get(\"child_internal_thought\", \"\"),\n        \"coach_feedback\": data.get(\"feedback\", \"\"),\n        \"coach_tip_or_demo\": suggestion.get(\"content\", \"\"),\n        \"coach_output_type\": suggestion.get(\"type\", \"\")\n    }","script_type":"python","retry_config":{"retry_enabled":false,"max_retries":3,"retry_interval":500},"try_catch_config":{"strategy":"noop"},"imported_dify":{"code":"import json\n\ndef clamp_score(value: int, min_value: int = 0, max_value: int = 100) -> int:\n    return max(min_value, min(max_value, value))\n\ndef main(llm_output: str) -> dict:\n    # 1. 安全解析 JSON\n    try:\n        # 如果模型偶尔带上 ```json ... ``` 包裹，需要做一点清理\n        cleaned_json = llm_output.strip().replace(\"```json\", \"\").replace(\"```\", \"\")\n        data = json.loads(cleaned_json)\n    except json.JSONDecodeError:\n        # 处理解析失败的情况，返回默认值或抛出错误\n        return {\"error\": \"Invalid JSON format\"}\n\n    # 2. 从字典中获取数据 (使用 get 提供默认值)\n    metrics = data.get(\"state_metrics\", {})\n    suggestion = data.get(\"suggestion_or_demo\", {})\n\n    mood_score_int = clamp_score(int(metrics.get(\"current_mood\", 40)))\n    progress_score_int = clamp_score(int(metrics.get(\"current_progress\", 0)))\n\n    # 3. 逻辑判定\n    task_completed = \"true\" if progress_score_int >= 100 else \"false\"\n    stage_next = \"roleplay_summary\" if task_completed == \"true\" else \"role_play\"\n\n    # 4. 组装返回字典\n    return {\n        \"child_response\": data.get(\"child_dialogue\", \"\"),\n        \"child_mood_state\": \", \".join(metrics.get(\"status\", [])),\n        \"child_mood_delta\": str(metrics.get(\"mood_change\", \"0\")),\n        \"child_mood_score\": str(mood_score_int),\n        \"task_progress_delta\": str(metrics.get(\"task_progress\", \"0\")),\n 