rite_mode":"over-write"}],"selected":false,"title":"变量赋值 11","type":"assigner","version":"2"}}},"position":{"x":2836,"y":1558},"width":242,"type":"VariableAssign"},{"id":"1779239207262","name":"直接回复 7","desc":"","config":{"input_params":[],"output_params":[],"node_param":{"output":"${1779179754877.output}","stream_switch":true,"imported_dify":{"answer":"{{#1779179754877.text#}}","selected":false,"title":"直接回复 7","type":"answer","variables":[]}}},"position":{"x":2494,"y":2522},"width":242,"type":"Output"},{"id":"1779249319750","name":"LLM 亲子沟通模拟场景确认","desc":"","config":{"input_params":[],"output_params":[{"key":"output","type":"String","desc":"文本输出"},{"key":"reasoning_content","type":"String","desc":"深度思考内容"}],"node_param":{"sys_prompt_content":"你是一个亲子沟通模拟场景确认助手。\n\n你的任务不是重新生成方案，也不是马上开始角色扮演，而是在家长选择或自定义模拟场景后，帮家长确认当前准备练习的场景。\n\n你会收到：\n1. 家长最初的问题${conversation.user_problem_raw}；\n2. 刚刚生成的亲子沟通方案：${conversation.plan_current}；\n4. 上一步整理好的模拟场景，包括“情境”和“练习重点”；\n5. 家长当前输入。\n\n你需要做两件事：\n\n第一，简要确认家长当前选择的模拟场景。\n第二，明确告诉家长：这个场景接下来可以用于模拟对练。\n\n请注意：\n1. 不要重新生成完整方案。\n2. 不要开始角色扮演。\n3. 不要扮演孩子。\n4. 不要长篇解释理论。\n5. 不要输出 JSON。\n6. 输出要简洁、清楚。\n7. 必须明确写出当前模拟场景的“情境”和“练习重点”。\n\n请严格按以下格式输出：\n\n为了方便你更好地落地本目标方案，特意为你准备了模拟场景：\n\n情境：________。\n练习重点：________。\n","prompt_content":"","short_memory":{"enabled":false,"type":"self","round":3,"param":{"key":"historyList","type":"Array<String>","value_from":"refer"}},"model_config":{"model_id":"qwen-plus-latest","model_name":"qwen-plus-latest","mode":"chat","provider":"4e0e12f3","params":[{"key":"temperature","value":0.7,"enable":true,"type":"Number"}],"vision_config":{"enable":false,"params":[{"key":"imageContent","value_from":"refer","type":"File"}]}},"retry_config":{"retry_enabled":false,"max_retries":3,"retry_interval":500},"try_catch_config":{"strategy":"noop","default_values":[{"key":"output","type":"String","desc":"文本输出"},{"key":"reasoning_content","type":"String","desc":"深度思考内容"}]},"structured_output_enabled":false,"structured_output_schema":{"type":"object","properties":{},"required":[],"additionalProperties":false},"imported_dify":{"context":{"enabled":false,"variable_selector":[]},"model":{"completion_params":{"temperature":0.7},"mode":"chat","name":"qwen-plus-latest","provider":"langgenius/tongyi/tongyi"},"prompt_template":[{"id":"57e8fa50-b121-49bc-856a-e244d0267c77","role":"system","text":"你是一个亲子沟通模拟场景确认助手。\n\n你的任务不是重新生成方案，也不是马上开始角色扮演，而是在家长选择或自定义模拟场景后，帮家长确认当前准备练习的场景。\n\n你会收到：\n1. 家长最初的问题{{#conversation.user_problem_raw#}}；\n2. 刚刚生成的亲子沟通方案：{{#conversation.plan_current#}}；\n4. 上一步整理好的模拟场景，包括“情境”和“练习重点”；\n5. 家长当前输入。\n\n你需要做两件事：\n\n第一，简要确认家长当前选择的模拟场景。\n第二，明确告诉家长：这个场景接下来可以用于模拟对练。\n\n请注意：\n1. 不要重新生成完整方案。\n2. 不要开始角色扮演。\n3. 不要扮演孩子。\n4. 不要长篇解释理论。\n5. 不要输出 JSON。\n6. 输出要简洁、清楚。\n7. 必须明确写出当前模拟场景的“情境”和“练习重点”。\n\n请严格按以下格式输出：\n\n为了方便你更好地落地本目标方案，特意为你准备了模拟场景：\n\n情境：________。\n练习重点：________。\n"}],"selected":false,"title":"LLM 亲子沟通模拟场景确认","type":"llm","vision":{"enabled":false}}}},"position":{"x":3178,"y":1608},"width":242,"type":"LLM"},{"id":"1779250445546","name":"代码执行 5","desc":"","config":{"input_params":[{"key":"llm_output","type":"String","value_from":"refer","value":"${1779249319750.output}"}],"output_params":[{"key":"practice_focus","type":"String","desc":""},{"key":"scene_standard","type":"String","desc":""},{"key":"situation","type":"String","desc":""}],"node_param":{"script_content":"import re\n\ndef main(llm_output: str) -> dict:\n    text = llm_output.strip()\n\n    # 去掉 Markdown 加粗符号\n    text = text.replace(\"**\", \"\")\n\n    situation = \"\"\n    practice_focus = \"\"\n\n    situation_match = re.search(\n        r\"情境[:：]\\s*(.*?)(?=\\n\\s*练习重点[:：])\",\n        text,\n        flags=re.S\n    )\n    if situation_match:\n        situation = situation_match.group(1).strip()\n\n    focus_match = re.search(\n        r\"练习重点[:：]\\s*(.*?)(?=\\n\\s*(接下来你可以选一个方向|A\\.|A．|请回复|$))\",\n        text,\n        flags=re.S\n    )\n    if focus_match:\n        practice_focus = focus_match.group(1).strip()\n\n    situation = re.sub(r\"\\s+\", \" \", situation).strip()\n    practice_focus = re.sub(r\"\\s+\", \" \", practice_focus).strip()\n\n    scene_standard = f\"情境：{situation}\\n练习重点：{practice_focus}\"\n\n    return {\n        \"situation\": situation,\n        \"practice_focus\": practice_focus,\n        \"scene_standard\": scene_standard\n    }","script_type":"python","retry_config":{"retry_enabled":false,"max_retries":3,"retry_interval":500},"try_catch_config":{"strategy":"noop"},"imported_dify":{"code":"import re\n\ndef main(llm_output: str) -> dict:\n    text = llm_output.strip()\n\n    # 去掉 Markdown 加粗符号\n    text = text.replace(\"**\", \"\")\n\n    situation = \"\"\n    practice_focus = \"\"\n\n    situation_match = re.search(\n        r\"情境[:：]\\s*(.*?)(?=\\n\\s*练习重点[:：])\",\n        text,\n        flags=re.S\n    )\n    if situation_match:\n        situation = situation_match.group(1).strip()\n\n    focus_match = re.search(\n        r\"练习重点[:：]\\s*(.*?)(?=\\n\\s*(接下来你可以选一个方向|A\\.|A．|请回复|$))\",\n        text,\n        flags=re.S\n    )\n    if focus_match:\n        practice_focus = focus_match.group(1).strip()\n\n    situation = re.sub(r\"\\s+\", \" \", situation).strip()\n    practice_focus = re.sub(r\"\\s+\", \" \", practice_focus).strip()\n\n    scene_standard = f\"情境：{situation}\\n练习重点：{practice_focus}\"\n\n    return {\n        \"situation\": situation,\n        \"practice_focus\": practice_focus,\n        \"scene_standard\": scene_standard\n    }","code_language":"python3","outputs":{"practice_focus":{"type":"string"},"scene_standard":{"type":"string"},"situation":{"type":"string"}},"selected":false,"title":"代码执行 5","type":"code","variables":[{"value_selector":["1779249319750","text"],"value_type":"string","variable":"llm_output"}]}}},"position":{"x":3862,"y":1626},"width":242,"type":"Script"},{"id":"1779251426837","name":"条件分支 4","desc":"","config":{"input_params":[],"output_params":[],"node_param":{"branches":[{"id":"true","label":"true","logic":"and","conditions":[{"ope